"use client";

import { useFormState } from "react-dom";
import { register } from "./actions";

export default function SignupPage() {
  const [state, formAction] = useFormState(register, null);

  return (
    <div className="flex flex-col items-center mt-20 bg-gradient-to-right from-blue-500 via-cyan-500 to-green-500 min-h-screen p-6">
      <h1 className="text-4xl font-extrabold mb-6 text-white">
        Registreren
      </h1>

      <form
        action={formAction}
        className="w-80 bg-white p-6 rounded-2xl shadow-xl space-y-4"
      >
        <input
          type="email"
          name="email"
          placeholder="E-mail"
          className="w-full p-2 border rounded"
          required
        />

        <input
          type="password"
          name="password"
          placeholder="Wachtwoord"
          className="w-full p-2 border rounded"
          required
        />

        <button
          type="submit"
          className="w-full bg-blue-600 text-white p-2 rounded"
        >
          Registreren
        </button>

        {/* 🔥 ERROR MESSAGE */}
        {state?.error && (
          <p className="text-red-500 text-sm">{state.error}</p>
        )}
      </form>
    </div>
  );
}